def life(a,birth={3},survive={2,3},steps=1):
 x=[row[:] for row in a]
 for _ in range(steps):
  h,w=len(x),len(x[0]); y=[[0]*w for _ in range(h)]
  for r in range(h):
   for c in range(w):
    n=sum(x[rr][cc] for rr in range(max(0,r-1),min(h,r+2)) for cc in range(max(0,c-1),min(w,c+2)) if (rr,cc)!=(r,c))
